import math

def check_quotient(n):
    if n < 0:
        return None
    numerator = 3 * ((n + 2) * math.factorial(n + 2) + 1)
    denominator = 2 * n - 1

    if denominator == 0:
        return "Undefined (Denominator is zero)"

    quotient = numerator / denominator

    # Check if the quotient is an integer
    is_integer = quotient == int(quotient)

    if is_integer:
        return int(quotient)
    else:
        return None

solutions_to_verify = [0, 1, 2, 4, 12]
results = {}
for n in solutions_to_verify:
    results[n] = check_quotient(n)

print("Verification results:")
for n, result in results.items():
    print(f"n={n}: Quotient = {result}")
